37	import { ChakraProvider, useBreakpointValue } from '@chakra-ui/react';
38	import { IntlProvider } from 'react-intl';
39	import { MemoryRouter } from 'react-router-dom';
40	import theme from 'app/theme';
41	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
42	import ItemVariantProvider from '.';
43	import CartItemVariantImage from './item-image';
44	import CartItemVariantName from './item-name';
45	import CartItemVariantAttributes from './item-attributes';
46	import CartItemVariantPrice from './item-price';
