59	
60	vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
61	  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
62	}));
63	
64	vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
65	  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
66	  return {
67	    ...actual,
68	    usePromotions: () => ({ data: undefined }),
69	    useProducts: () => ({ data: undefined, isLoading: false }),
