74	vi.mock('@chakra-ui/react', async (importOriginal) => {
75	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
76	  return {
77	    ...actual,
78	    useBreakpointValue: vi.fn(),
79	  };
80	});
