82	const mockUseMultiSite = vi.mocked(useMultiSite);
83	const mockUseBreakpointValue = vi.mocked(useBreakpointValue);
84	
85	// ChakraProvider with this project's own theme is required, not optional here — without it,
86	// `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
87	// `useBreakpointValue` (item-price.tsx, exercised transitively were this file to render it)
88	// throws outright reading `theme.breakpoints` off an undefined theme. Same setup zimmButton's
89	// own test uses.
90	const renderWithProviders = (ui: React.ReactElement) =>
91	  render(
92	    <ChakraProvider theme={theme}>
93	      <MemoryRouter>
94	        <IntlProvider locale="en-AU" defaultLocale="en-AU">
95	          {ui}
96	        </IntlProvider>
97	      </MemoryRouter>
98	    </ChakraProvider>,
99	  );
