101	const baseVariant = {
102	  id: 'variant-1',
103	  productName: 'Lilac Sand Dress',
104	  imageGroups: [
105	    {
106	      viewType: 'small',
107	      images: [{ alt: 'Lilac Sand Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
108	    },
109	  ],
110	};
111	
112	describe('item-variant', () => {
113	  beforeEach(() => {
114	    mockUseMultiSite.mockReturnValue({
115	      site: { id: 'ZimmermannAU' },
116	      buildUrl: (path: string) => path,
117	    });
118	  });
119	
120	  describe('CartItemVariantImage (item-image) — defaults-then-spread', () => {
121	    test('a caller-supplied width wins over the Zimmermann default', () => {
122	      const { container } = renderWithProviders(
123	        <ItemVariantProvider variant={baseVariant}>
124	          <CartItemVariantImage width="321px" />
125	        </ItemVariantProvider>,
126	      );
127	      const box = container.firstElementChild as HTMLElement;
128	      expect(box).toHaveStyle({ width: '321px' });
129	    });
130	
131	    test('a caller-supplied mr is applied (the exact regression that would break order-summary)', () => {
132	      const { container } = renderWithProviders(
133	        <ItemVariantProvider variant={baseVariant}>
134	          <CartItemVariantImage mr="37px" />
135	        </ItemVariantProvider>,
136	      );
137	      const box = container.firstElementChild as HTMLElement;
138	      expect(box).toHaveStyle({ marginRight: '37px' });
139	    });
140	  });
141	
142	  describe('CartItemVariantName (item-name) — spread-order bug fix', () => {
143	    test('a caller-supplied color wins over the Zimmermann default', () => {
144	      renderWithProviders(
145	        <ItemVariantProvider variant={baseVariant}>
146	          <CartItemVariantName color="rgb(255, 0, 0)" />
147	        </ItemVariantProvider>,
148	      );
149	      const link = screen.getByRole('link', { name: 'Lilac Sand Dress' });
150	      expect(link).toHaveStyle({ color: 'rgb(255, 0, 0)' });
151	    });
152	
153	    test('renders uppercase via textStyle="productNames" (text-transform, not literal casing)', () => {
154	      renderWithProviders(
155	        <ItemVariantProvider variant={baseVariant}>
156	          <CartItemVariantName />
157	        </ItemVariantProvider>,
158	      );
159	      // Asserted on the <Heading> textStyle is actually applied to, not the nested <Link> —
160	      // text-transform is CSS-inherited from parent to child, and jsdom's getComputedStyle does
161	      // not reliably resolve inherited (as opposed to directly-applied) declarations.
162	      const heading = screen.getByRole('heading', { level: 2 });
163	      expect(heading).toHaveStyle({ textTransform: 'uppercase' });
164	    });
165	  });
166	
167	  describe('CartItemVariantAttributes (item-attributes) — combineAttributeValues default (per-key) path', () => {
168	    // Shape matches getDisplayVariationValues's own real contract (product-utils.js) — the real,
169	    // unmocked utility is exercised here, not stubbed, since this test is specifically about the
170	    // per-key rendering path's own contract.
171	    const attributesVariant = {
172	      id: 'variant-1',
173	      productName: 'Lilac Sand Dress',
174	      variationAttributes: [
175	        { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
176	        { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
177	      ],
178	      variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
179	    };
180	
181	    // Round 2 rework (must-fix 2): this branch has six real, unmodified callers today
182	    // (order-summary, wishlist partials, checkout partials, account/order-detail, the
183	    // confirmation page) and none of them pass combineAttributeValues — this proves this
184	    // build's new `!combineAttributeValues &&` guard still renders their per-key output.
185	    test('renders one Text per variation-value key, with labels, when combineAttributeValues is omitted', () => {
186	      renderWithProviders(
187	        <ItemVariantProvider variant={attributesVariant}>
188	          <CartItemVariantAttributes />
189	        </ItemVariantProvider>,
190	      );
191	
192	      expect(screen.getByText('Colour: Lilac Sand')).toBeInTheDocument();
193	      expect(screen.getByText('Size: One Size')).toBeInTheDocument();
194	      // Not the combined-string shape — proves the per-key branch rendered, not the combined one.
195	      expect(screen.queryByText('Lilac Sand, One Size')).not.toBeInTheDocument();
196	    });
197	
198	    test('hideAttributeLabels still renders per-key (one Text per key), just without the "Key: " prefix', () => {
199	      renderWithProviders(
200	        <ItemVariantProvider variant={attributesVariant}>
201	          <CartItemVariantAttributes hideAttributeLabels />
202	        </ItemVariantProvider>,
203	      );
204	
205	      expect(screen.getByText('Lilac Sand')).toBeInTheDocument();
206	      expect(screen.getByText('One Size')).toBeInTheDocument();
207	      expect(screen.queryByText('Colour: Lilac Sand')).not.toBeInTheDocument();
208	    });
209	  });
210	
211	  describe('CartItemVariantPrice (item-price) — rendering logic', () => {
212	    const priceVariant = (overrides: Record<string, unknown> = {}) => ({
213	      id: 'variant-1',
214	      itemId: 'item-1',
215	      name: 'Lilac Sand Dress',
216	      price: 200,
217	      priceAfterItemDiscount: 200,
218	      pricePerUnit: 100,
219	      quantity: 2,
220	      ...overrides,
221	    });
222	
223	    test('isDesktop-gated positioning: PricePerItem renders before the main price on mobile, after it on desktop', () => {
224	      mockUseBreakpointValue.mockReturnValue(false);
225	      const mobile = renderWithProviders(
226	        <ItemVariantProvider variant={priceVariant()}>
227	          <CartItemVariantPrice currency="AUD" />
228	        </ItemVariantProvider>,
229	      );
230	      const perItemMobile = screen.getByText('$100.00ea');
231	      const mainPriceMobile = screen.getByText('$200.00');
232	      // Node.DOCUMENT_POSITION_FOLLOWING: mainPrice comes AFTER perItem in document order.
233	      expect(perItemMobile.compareDocumentPosition(mainPriceMobile) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
234	      mobile.unmount();
235	
236	      mockUseBreakpointValue.mockReturnValue(true);
237	      renderWithProviders(
238	        <ItemVariantProvider variant={priceVariant()}>
239	          <CartItemVariantPrice currency="AUD" />
240	        </ItemVariantProvider>,
241	      );
242	      const perItemDesktop = screen.getByText('$100.00ea');
243	      const mainPriceDesktop = screen.getByText('$200.00');
244	      // Reversed: perItem now comes AFTER mainPrice.
245	      expect(
246	        mainPriceDesktop.compareDocumentPosition(perItemDesktop) & Node.DOCUMENT_POSITION_FOLLOWING,
247	      ).toBeTruthy();
248	    });
249	
250	    test('isOnSale collapses the price Stack spacing to 0, otherwise theme.space[1] (0.25rem)', () => {
251	      mockUseBreakpointValue.mockReturnValue(false);
252	
253	      const notOnSale = renderWithProviders(
254	        <ItemVariantProvider variant={priceVariant({ price: 200, priceAfterItemDiscount: 200, quantity: 1 })}>
255	          <CartItemVariantPrice currency="AUD" />
256	        </ItemVariantProvider>,
257	      );
258	      const notOnSaleStack = notOnSale.container.firstElementChild as HTMLElement;
259	      // Chakra/emotion emits a CSS custom-property reference for a registered space-scale
260	      // value, not the literal rem — confirmed by reading the actual rendered style, not assumed.
261	      expect(notOnSaleStack).toHaveStyle({ gap: 'var(--chakra-space-1)' });
262	      notOnSale.unmount();
263	
264	      const onSale = renderWithProviders(
265	        <ItemVariantProvider variant={priceVariant({ price: 250, priceAfterItemDiscount: 200, quantity: 1 })}>
266	          <CartItemVariantPrice currency="AUD" />
267	        </ItemVariantProvider>,
268	      );
269	      const onSaleStack = onSale.container.firstElementChild as HTMLElement;
270	      // Unlike space[1] above, Chakra's own default scale has no `0` key at all (confirmed by
271	      // reading @chakra-ui/theme's spacing chunk) — so `spacing={0}` isn't a scale lookup, it's
272	      // the literal value passed straight through, rendering as a plain `0px`, not a CSS var.
273	      expect(onSaleStack).toHaveStyle({ gap: '0px' });
274	    });
275	
276	    test('applies the price recipe (textStyle) directly to its own Stack', () => {
277	      mockUseBreakpointValue.mockReturnValue(false);
278	      const { container } = renderWithProviders(
279	        <ItemVariantProvider variant={priceVariant({ quantity: 1 })}>
280	          <CartItemVariantPrice currency="AUD" />
281	        </ItemVariantProvider>,
282	      );
283	      const stack = container.firstElementChild as HTMLElement;
284	      // theme/foundation/typography.ts's `price` textStyle: fontSize '2xs' (0.875rem), fontWeight
285	      // medium (500) — verified against the real registered scale, not assumed.
286	      expect(stack).toHaveStyle({ fontSize: '0.875rem', fontWeight: '500' });
287	    });
288	  });
289	});
