/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-price.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below and a temporary
 * `[overrides]` console.log marker (verified live, then removed). The
 * `<Stack textAlign={align} ... {...props}>`
 * defaults-then-spread prop order is preserved exactly, unchanged from base.
 *
 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
 * `display-price` and the `useCurrency`/`app/hooks` barrel are not overridden anywhere in this
 * repo (verified by directory listing at time of writing), so both stay on the base
 * `@salesforce/retail-react-app/...` path.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec (`textStyle="price"`) via
 * item-variant.css.ts's `price` part. The actual price digits render via the base,
 * un-overridden `display-price`/`current-price` components below (out of this commit's file
 * scope) — confirmed by reading both that neither sets its own competing font-size, so the
 * textStyle cascades down via ordinary CSS inheritance rather than needing either file touched.
 * `PricePerItem`'s own `fontSize={{base: '12px', lg: '14px'}}` is untouched — no Figma value
 * was given for it at this step.
 */
import React from 'react';
import { FormattedMessage, FormattedNumber } from 'react-intl';
import {
  Stack,
  Text,
  useBreakpointValue,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
// redeclared per file.
import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

type PricePerItemProps = {
  currency: string;
  // Deviation from the base file (same labelled-comment convention as
  // product-view/index.tsx:659-661/1019-1022): base PropTypes declares this as optional
  // (`PropTypes.number`, no `.isRequired`), but both real call sites below it — the only two
  // in this file — only ever render <PricePerItem> from behind a `priceData?.pricePerUnit &&`
  // guard, so `basePrice` is never actually undefined when this renders. Typed as required to
  // satisfy `<FormattedNumber value={basePrice} />`'s `number | bigint` prop under strict null
  // checks, without inventing a fallback value the base file never had.
  basePrice: number;
};

const PricePerItem = ({ currency, basePrice }: PricePerItemProps) => {
  return (
    <Text fontSize={{ base: '12px', lg: '14px' }}>
      <FormattedNumber style="currency" currency={currency} value={basePrice} />
      <FormattedMessage
        defaultMessage="ea"
        id="price_per_item.label.each"
        description="Abbreviated 'each', follows price per item, like $10/ea"
      />
    </Text>
  );
};

type ItemPriceProps = {
  currency: string;
  align?: string;
  baseDirection?: string;
} & Record<string, any>;

/**
 * In the context of a cart product item variant, this component renders the item's
 * pricing, taking into account applied discounts as well as base item prices.
 */
const ItemPrice = ({ currency, align = 'right', baseDirection = 'column', ...props }: ItemPriceProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
  const { price, priceAfterItemDiscount } = variant;
  const isASet = variant?.type?.set;
  const isMaster = variant?.type?.master;
  let priceData;
  // When variant has basket pricing, we should prioritize these prices for displaying
  // since they may have take promotion/discount into account
  // NOTE: try NOT to re-calculate these values since basket-level discount is complicated
  if (variant?.itemId) {
    priceData = {
      currentPrice: priceAfterItemDiscount,
      // we don't want to show strikethrough price for cart since listPrice is not available via basket pricing
      listPrice: null,
      pricePerUnit: variant?.pricePerUnit,
      isASet,
      isMaster,
      isRange: isASet || isMaster || false,
      isOnSale: price > priceAfterItemDiscount,
    };
  } else {
    // for wishlist page we extract price info from variant/product obj
    priceData = getPriceData(variant);
  }
  const isDesktop = useBreakpointValue({ base: false, lg: true });

  return (
    <Stack
      sx={styles.price}
      textAlign={align}
      direction={baseDirection}
      justifyContent={align === 'left' ? 'flex-start' : 'flex-end'}
      alignItems="baseline"
      spacing={priceData?.isOnSale ? 0 : 1}
      wrap="nowrap"
      {...props}
    >
      {!isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
      )}

      {variant?.itemId ? (
        <DisplayPrice
          labelForA11y={variant?.name}
          currency={currency}
          priceData={priceData}
          listPriceProps={{ fontSize: 'sm' }}
        />
      ) : (
        <DisplayPrice
          labelForA11y={variant?.name}
          currency={currency}
          priceData={priceData}
          quantity={variant?.quantity}
          listPriceProps={{ fontSize: 'sm' }}
        />
      )}

      {isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
      )}
    </Stack>
  );
};

export default ItemPrice;
